function header(title,{back=false,logo=false,brand=false,audio=false,food=false,gear=false}={}){return `<header class="top"><div class="status"><span>9:41</span><span class="signal">${icon('signal')}${icon('wifi')}${icon('battery-full')}</span></div><div class="heading">${back?`<button class="icon-button" data-action="back" aria-label="Go back">${icon('arrow-left')}</button>`:''}${logo?'<img class="logo" src="assets/logo.webp" alt="Numbeast">':`${brand?'<img class="monogram" src="assets/monogram.webp" alt="Numbeast">':''}<strong>${escape(title)}</strong>`}<span class="push"></span>${audio?listen():''}${food?`<span class="pill" aria-label="${state.food} apples">${icon('apple')} ${state.food}</span>`:''}${gear?`<button class="icon-button" data-action="settings" aria-label="Parent settings">${icon('settings')}</button>`:''}</div></header>`}
function nav(active){return `<nav class="bottom" aria-label="Main navigation">${[['camp','Camp','tent-tree'],['map','Adventure','compass'],['beasts','Beasts','paw-print']].map(([key,label,ic])=>`<button class="tab ${active===key?'active':''}" data-go="${key}" aria-label="${label}" ${active===key?'aria-current="page"':''}>${icon(ic)}${label}</button>`).join('')}</nav>`}
const action=(label,key,secondary=false)=>`<footer class="bottom action"><button class="${secondary?'secondary':'primary'}" data-action="${key}">${label}</button></footer>`;
const intro=(title,copy)=>`<div class="intro" data-read><h1>${title}</h1>${copy?`<p class="muted">${copy}</p>`:''}</div>`;const readRow=()=>`<div class="read-row">${listen()}</div>`;const note=(title,copy,ic='heart',extra='')=>`<div class="note ${extra}">${icon(ic)}<div><h3>${title}</h3><p class="muted">${copy}</p></div></div>`;
function go(screen,options={}){stopSpeech();state.screen=screen;state.counted.clear();render(options);if(state.autoRead&&screen!=='welcome'&&!state.director&&options.read!==false)setTimeout(()=>{if(state.screen===screen)speak(prompt())},340)}
function prompt(){const f=family();switch(state.screen){case'welcome':return 'Welcome to Numbeast. Play quests. Feed your beast. Watch it grow. Tap Play to start.';case'nickname':return 'Pick a nickname. What should your beast call you?';case'eggs':return 'Pick your beast. Splashle is water. Flamfox is fire. Rollie is earth. Breeflap is air. Pick any egg, then tap Choose.';case'hatch':return `Hello, ${f.name}! Your new friend is here. Play quests to help your beast grow.`;case'camp':return 'Your beast is ready. Tap Explore to play a quest.';case'map':return state.progress===5?'You finished all five quests. Great teamwork!':`${state.progress} of five quests done. ${quests[state.progress][0]} is next. Tap the gold flag to play.`;case'lesson':return lessons[state.lesson].say;case'hint':return lessons[state.lesson].hint+' '+({count:'Four plus four equals eight.',compare:'Nine is greater than six.',add:'Seven plus three plus two equals twelve.',subtract:'Twelve minus two minus three equals seven.',multiply:'Four plus four plus four equals twelve.',divide:'Twelve divided by three equals four.',fraction:'Three out of four is three quarters.',decimal:'Zero point seven five is greater than zero point five.',pattern:'Crystal, apple, crystal.'})[state.lesson];case'reward':return 'You did it! One apple and ten XP for your beast.';case'evolve':return `${f.name} grew! Look how much bigger your beast is now.`;case'food':return state.food?'Give your beast one apple. Tap Feed my beast.':'Your bag is empty. Play a quest to find more apples.';case'family':return "Meet the five forms. Play quests to help your beast grow. Come back whenever you are ready.";case'beasts':return 'Meet the beasts. Tap a family to see all five forms.';case'practice':return 'Pick a practice quest. Counting, comparing, adding, taking away, multiplying, dividing, fractions, decimals, or patterns.';default:return 'Tap a button to keep exploring.'}}
function updateReading(){document.querySelectorAll('.listen').forEach(el=>{el.classList.toggle('speaking',state.reading);el.innerHTML=(state.reading?'<span class="wave"><i></i><i></i><i></i><i></i></span>':icon('volume-2'))+`<span>${state.reading?'Stop':'Listen'}</span>`;el.setAttribute('aria-label',state.reading?'Stop reading':'Read this screen aloud')});document.querySelectorAll('[data-read]').forEach(el=>el.classList.toggle('reading',state.reading))}
function stopSpeech(){speechToken++;if('speechSynthesis'in window)speechSynthesis.cancel();narration.pause();narration.onended=null;narration.onerror=null;state.reading=false;updateReading()}
function speak(words){if(state.muted)return Promise.resolve();stopSpeech();const token=speechToken;state.reading=true;updateReading();return new Promise(resolve=>{const end=()=>{if(token===speechToken){state.reading=false;updateReading()}resolve()};if(AUDIO[words]){narration.src=AUDIO[words];narration.playbackRate=state.rate/.93;narration.onended=end;narration.onerror=end;narration.play().catch(()=>{end();toast('Tap Listen to hear the prompt.');});setTimeout(end,Math.max(10000,words.length*140));return}if(!('speechSynthesis'in window)){end();toast('Tap a quest to explore.');return}const u=new SpeechSynthesisUtterance(words);u.lang='en-US';u.rate=state.rate;u.pitch=1.05;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>/Jenny|Aria|Samantha|Google US English|Zira/i.test(v.name))||voices.find(v=>v.lang.startsWith('en'))||null;u.onend=end;u.onerror=end;speechSynthesis.speak(u);setTimeout(end,Math.max(6000,words.length*115));})}
function visual(key,hint=false){const apples=n=>`<div class="objects">${Array.from({length:n},(_,i)=>`<button data-count="${i}" aria-label="Apple ${i+1}" ${key==='subtract'&&i<5?'style="opacity:.2"':''}>${icon('apple')}${state.counted.has(i)?`<span class="count-label">${i+1}</span>`:''}</button>`).join('')}</div>`;if(key==='count')return apples(8);if(key==='subtract')return apples(12);if(key==='compare')return `<div class="groups">${[['A',6],['B',9]].map(([l,n])=>`<div class="compare-pile"><h3>${l}</h3><div class="dots">${Array(n).fill(icon('gem')).join('')}</div></div>`).join('')}</div>`;if(key==='multiply'||key==='divide')return `<div class="groups">${Array(3).fill(`<div class="pile">${Array(4).fill(icon('gem')).join('')}</div>`).join('')}</div>`;if(key==='fraction')return `<div class="charge-row">${[1,1,1,0].map(n=>`<span class="charge ${n?'on':''}">${n?icon('zap'):''}</span>`).join('')}</div>`;if(key==='decimal')return [['0.5',2],['0.75',3]].map(([v,n])=>`<div class="charge-row"><strong>${v}</strong>${[0,1,2,3].map(i=>`<span class="charge ${i<n?'on':''}">${i<n?icon('zap'):''}</span>`).join('')}</div>`).join('');if(key==='pattern')return `<div class="groups" style="align-items:center">${['gem','apple','gem','apple'].map(i=>`<span class="charge ${i==='gem'?'on':''}">${icon(i)}</span>`).join('')}<strong style="font-size:32px">?</strong></div>`;return '<div class="equation"><span>7</span><span>+</span><span>5</span></div>'}
function render(options={}){renderToken++;const f=family();let head='',content='',foot='';const rw=readRow();if(state.screen==='welcome'){head=header('',{logo:true,audio:true});content=`<div class="pad">${intro('Your beast. Your adventure!','Play quests. Feed your beast. Watch it grow.')}<div class="hero four">${families.map(x=>sprite(x,1)).join('')}</div><div class="trio">${[['compass','Explore'],['gem','Solve'],['paw-print','Grow']].map(([i,t])=>`<div>${icon(i)}${t}</div>`).join('')}</div><button class="link" data-action="settings">For parents ${icon('chevron-right')}</button></div>`;foot=action('Play','start')}
else if(state.screen==='nickname'){head=header('Your explorer',{back:true});content=`<div class="pad">${rw}${intro('Pick a nickname.','What should your beast call you?')}<div class="hero" style="height:190px">${sprite(f,1)}</div><label class="field">Nickname<input id="nickname" maxlength="16" autocomplete="off" value="${escape(state.nickname)}"></label><small>A nickname is best.</small></div>`;foot=action('Next','save-name')}
else if(state.screen==='eggs'){head=header('Pick your beast',{back:true});content=`<div class="pad">${rw}${intro('Pick your beast.','Pick any egg. They all love adventures.')}<div class="egg-grid">${families.map((x,i)=>`<button class="egg ${i===state.family?'active':''}" data-family="${i}" aria-pressed="${i===state.family}" style="--element:${x.color};--soft:${x.soft}"><span class="egg-art"><img src="assets/${x.key}-egg.webp" alt="${x.element} egg"></span>${x.name}<small>${i===state.family?'✓ ':''}${x.element}</small></button>`).join('')}</div></div>`;foot=action('Choose '+f.name,'hatch')}
else if(state.screen==='hatch'){head=header('A new friendship',{back:true});content=`<div class="pad">${rw}${intro('Hello, '+f.name+'!','Your new friend is here.')}<div class="hero evolve">${sprite(f,1)}</div>${note('Help your beast grow','Play quests to help your beast grow.','heart')}</div>`;foot=action('Let’s go','camp')}
else if(state.screen==='camp'){head=header('Camp',{brand:true,food:true,gear:true});content=`<div class="hero camp-hero" style="height:${Math.max(280,[0,128,176,240,320,416][state.stage]*.9+64)}px">${sprite()}</div><div class="pad">${rw}<div class="card"><h3>${f.name} · ${['','Hatchling','Scout','Guardian','Champion','Titan'][state.stage]}</h3><div class="progress-track"><span style="width:${state.xp%30/30*100}%"></span></div><small>${state.xp%30} of 30 XP · ${state.progress} of 5 quests done</small></div><div class="two"><button data-go="food">${icon('apple')} Feed</button><button data-go="beasts">${icon('book-open')} My beasts</button></div>${note(state.progress===5?'All quests done!':'Ready to explore?',state.progress===5?'Try any quest again.':quests[state.progress][0]+' is next.','compass')}<button class="primary" data-go="map">Explore</button></div>`;foot=nav('camp')}
else if(state.screen==='map'){head=header('Adventure',{audio:true});content=`<div class="world"><div class="map-progress" role="status">${state.progress} of 5 done</div>${[[128,428],[281,322],[104,252],[274,133],[176,68]].map(([x,y],i)=>`<button class="quest-node ${i<state.progress?'done':i===state.progress?'current':'locked'}" style="left:${x/393*100}%;top:${y/490*100}%" data-quest="${i}" aria-label="${quests[i][0]}, ${i<state.progress?'complete':i===state.progress?'play next':'locked'}">${icon(i<state.progress?'check':i===state.progress?'flag':'lock-keyhole')}${i===state.progress?'<span class="tag">Play next</span>':''}</button>`).join('')}</div><div class="pad">${intro(state.progress===5?'You lit the lighthouse!':quests[state.progress][0],state.progress===5?'All 5 quests done. Great teamwork!':quests[state.progress][1])}<button class="primary" data-action="play-next">${state.progress===5?'My camp':'Play quest'}</button><button class="link" data-go="practice">Practice any skill ${icon('chevron-right')}</button></div>`;foot=nav('map')}
else if(state.screen==='practice'){head=header('Practice',{back:true});content=`<div class="pad">${rw}${intro('Pick a practice quest.','Play again. Get stronger.')}${Object.entries(lessons).map(([k,l])=>`<button class="trail" data-practice="${k}"><span class="tile">${icon(k==='count'||k==='subtract'?'apple':k==='fraction'?'shield-check':'gem')}</span><span class="words"><strong>${l.title}</strong><small>${l.copy}</small></span>${icon('chevron-right')}</button>`).join('')}</div>`;foot=nav('map')}
else if(state.screen==='lesson'||state.screen==='hint'){const l=lessons[state.lesson],hint=state.screen==='hint';head=header(hint?'Let’s try together':'Quest '+(state.worldGoal||'practice'),{back:true});content=`<div class="pad">${rw}${intro(hint?'Let’s work it out.':l.title,hint?l.hint:l.copy)}<div class="visual" data-read>${visual(state.lesson,hint)}</div>${hint?`<div class="card" style="background:#e3f1f1;text-align:center"><h2>${l.equation}</h2></div>${note('You can try again!','Hints help you learn.','lightbulb')}`:`<h3 data-read>${l.question}</h3><div class="answers">${l.values.map(v=>`<button class="answer" data-answer="${escape(v)}" aria-label="${escape(v)}">${escape(v)}</button>`).join('')}</div>`}</div>`;foot=action(hint?'Try again':'Help me',hint?'try-again':'help',!hint)}
else if(state.screen==='reward'){head=header('Quest complete');content=`<div class="pad result">${rw}${intro('You did it!','An apple and XP for your beast!')}<div class="celebrate">${icon('flag')}${Array.from({length:12},(_,i)=>`<span class="star" style="left:${10+i*7}%;top:65%;--x:${(i-6)*15}px;animation-delay:${i*.04}s">✦</span>`).join('')}</div><div class="reward-grid"><div class="card">${icon('zap')}<strong>+10</strong><span>XP</span></div><div class="card">${icon('apple')}<strong>+1</strong><span>Apple</span></div></div><div class="card"><h3>${f.name} is growing.</h3><div class="progress-track"><span style="width:${state.xp%30/30*100}%"></span></div><small>${state.xp%30} of 30 XP to the next form</small></div></div>`;foot=action(state.pendingEvolution?'See my beast grow':'Keep exploring','claim')}
else if(state.screen==='evolve'){head=header('A bigger beast');content=`<div class="pad result">${rw}${intro(f.name+' grew!','Look how much bigger your beast is.')}<div class="hero evolve" style="height:340px">${sprite()}</div><div class="card"><h2>${['','Hatchling','Scout','Guardian','Champion','Titan'][state.stage]}</h2><p>Ready for the next adventure!</p></div></div>`;foot=action('Keep exploring','finish-evolve')}
else if(state.screen==='food'){head=header('Snack time',{back:true});content=`<div class="hero camp-hero">${sprite()}</div><div class="pad">${rw}${intro(state.food?'Time for a snack?':'Let’s find more food.',state.food?'Give your beast one apple.':'Play a quest to earn an apple.')}${note(state.food+' '+(state.food===1?'apple':'apples')+' in your bag',state.food?'One apple for your beast.':'Your beast will wait for you.','apple','gold')}</div>`;foot=action(state.food?'Feed my beast':'Find a quest',state.food?'feed':'map')}
else if(state.screen==='beasts'){head=header('My beasts',{back:true});content=`<div class="pad">${rw}${intro('Meet the beasts.','Meet all four families.')}<div class="family-grid">${families.map((x,i)=>`<button class="family" data-detail="${i}"><span class="egg-art">${sprite(x,2)}</span>${x.name}<small>${x.element} · 5 forms</small></button>`).join('')}</div></div>`;foot=nav('beasts')}
else if(state.screen==='family'){const x=families[state.detail||0];head=header(x.name,{back:true});content=`<div class="pad">${rw}<div class="hero" style="height:240px">${sprite(x,3)}</div>${intro('Watch them grow.','Play quests to unlock each new form.')}<div class="card"><h3>Five forms. One friend.</h3><div class="growth">${[1,2,3,4,5].map((n)=>`<span class="form"><img src="assets/${x.key}-stage-${n}.webp" alt="${x.name}, form ${n}"><small>${n}</small></span>`).join('')}</div></div>${note('Your beast will wait','Come back whenever you’re ready.','heart')}</div>`;foot=action('My camp','camp')}
phone.innerHTML=head+`<div class="scroll screen-enter">${content}</div>`+foot+'<div class="tap-pointer" aria-hidden="true"></div><span class="sr-only" id="announcer" aria-live="polite"></span>';bind();if(options.scroll){phone.querySelector('.scroll').scrollTop=options.scroll}}
function bind(){phone.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));phone.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{state.family=+b.dataset.family;stopSpeech();render();if(!state.director)speak(family().name+'. '+family().element+'.')});phone.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{state.detail=+b.dataset.detail;state.form=3;go('family')});phone.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{state.lesson=b.dataset.practice;state.worldGoal=0;go('lesson')});phone.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>{const i=+b.dataset.quest;if(i>state.progress){toast('Play the gold flag first.');speak('Play the gold flag first.');return}state.lesson=quests[i][2];state.worldGoal=i+1;go('lesson')});phone.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(b.dataset.answer,b));phone.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{const i=+b.dataset.count;if(state.counted.has(i))return;state.counted.add(i);b.innerHTML+=`<span class="count-label">${state.counted.size}</span>`;if(!state.muted)speak(String(state.counted.size))});phone.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action))}
function act(key){if(key==='listen'){state.reading?stopSpeech():speak(prompt());return}if(key==='settings'){settings();return}if(key==='back'){go(({nickname:'welcome',eggs:'nickname',hatch:'eggs',food:'camp',family:'beasts',lesson:'map',hint:'lesson',practice:'map',beasts:'camp'})[state.screen]||'camp');return}if(key==='start'){state.autoRead=true;go('nickname',{read:false});speak(prompt());return}if(key==='save-name'){const n=document.querySelector('#nickname');state.nickname=n.value.trim()||'Alex';go('eggs');return}if(key==='hatch'){go('hatch');return}if(key==='play-next'){if(state.progress===5){go('camp');return}state.lesson=quests[state.progress][2];state.worldGoal=state.progress+1;go('lesson');return}if(key==='help'){go('hint');return}if(key==='try-again'){go('lesson');return}if(key==='claim'){go(state.pendingEvolution?'evolve':state.worldGoal?'map':'camp');return}if(key==='finish-evolve'){state.pendingEvolution=false;go(state.worldGoal?'map':'camp');return}if(key==='feed'){if(!state.food)return;state.food--;go('camp',{read:false});toast('Yum! One happy beast.');speak('Yum! One happy beast.');const s=phone.querySelector('.sprite');s.style.animation='answer-pop .5s';return}go(key)}
async function answer(value,b){if(phone.querySelector('.answer.correct'))return;stopSpeech();const l=lessons[state.lesson];if(value!==l.correct){b.classList.add('wrong');await wait(650);go('hint');return}b.classList.add('correct');phone.querySelectorAll('.answer').forEach(x=>x.disabled=true);const oldStage=state.stage;state.xp+=10;state.food++;if(state.worldGoal>state.progress)state.progress=state.worldGoal;state.stage=Math.min(5,1+Math.floor(state.xp/30));state.pendingEvolution=state.stage>oldStage;await wait(900);go('reward')}
function toast(text){phone.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.setAttribute('role','status');n.textContent=text;phone.appendChild(n);setTimeout(()=>n.remove(),3000)}
function settings(){stopSpeech();const d=document.createElement('div');d.className='modal-backdrop';d.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="Parent settings"><header><h2>Parent corner</h2><button class="icon-button" id="close-settings" aria-label="Close settings">${icon('x')}</button></header><p>Choose how the adventure sounds.</p><div class="setting"><span>Voice guide</span><button id="auto-read" class="toggle ${state.autoRead?'on':''}" role="switch" aria-checked="${state.autoRead}" aria-label="Voice guide"></button></div><div class="setting"><span>Sound on</span><button id="sound" class="toggle ${!state.muted?'on':''}" role="switch" aria-checked="${!state.muted}" aria-label="Sound on"></button></div><div class="setting"><span>Slower voice</span><button id="slow" class="toggle ${state.rate<.9?'on':''}" role="switch" aria-checked="${state.rate<.9}" aria-label="Slower voice"></button></div><button class="primary" id="done-settings">Done</button></section>`;phone.appendChild(d);d.querySelector('#close-settings').onclick=d.querySelector('#done-settings').onclick=()=>d.remove();const toggle=(id,fn,val)=>d.querySelector('#'+id).onclick=e=>{fn();e.currentTarget.classList.toggle('on',val());e.currentTarget.setAttribute('aria-checked',val())};toggle('auto-read',()=>state.autoRead=!state.autoRead,()=>state.autoRead);toggle('sound',()=>{state.muted=!state.muted;stopSpeech()},()=>!state.muted);toggle('slow',()=>state.rate=state.rate<.9?.93:.78,()=>state.rate<.9);d.querySelector('#close-settings').focus()}
async function tap(selector,token){if(token!==directorToken)throw new Error('stopped');const el=phone.querySelector(selector);if(!el)throw new Error('Missing presentation control '+selector);await wait(180);const a=el.getBoundingClientRect(),p=phone.getBoundingClientRect(),pointer=phone.querySelector('.tap-pointer');pointer.style.left=a.left-p.left+a.width/2-12+'px';pointer.style.top=a.top-p.top+a.height/2-12+'px';pointer.style.opacity='1';await wait(340);pointer.classList.add('down');await wait(140);el.click();await wait(170);pointer.classList.remove('down');await wait(300)}
async function present(){if(state.director){directorToken++;state.director=false;stopSpeech();document.querySelector('#present').textContent='▶ Present demo';return}const token=++directorToken;state.director=true;state.progress=0;state.xp=0;state.stage=1;state.food=1;state.family=0;state.nickname='Alex';state.pendingEvolution=false;document.querySelector('#present').textContent='■ Stop demo';go('welcome',{read:false});try{await wait(650);await tap('[data-action="start"]',token);await wait(300);const field=phone.querySelector('#nickname');field.value='';for(const c of 'Alex'){field.value+=c;await wait(110)}await tap('[data-action="save-name"]',token);await wait(350);await tap('[data-family="1"]',token);await wait(450);await tap('[data-family="0"]',token);await wait(350);await tap('[data-action="hatch"]',token);await wait(1000);await tap('[data-action="camp"]',token);await wait(500);await tap('[data-go="map"]',token);await wait(650);for(let n=0;n<3;n++){await tap('.quest-node.current',token);await wait(250);await tap('[data-action="listen"]',token);while(state.reading&&token===directorToken)await wait(150);await wait(250);await tap('[data-answer="'+lessons[state.lesson].correct+'"]',token);await wait(1000);await tap('[data-action="claim"]',token);await wait(850);if(state.screen==='evolve'){await wait(1000);await tap('[data-action="finish-evolve"]',token);await wait(700)}}await tap('[data-go="camp"]',token);await wait(1600);}catch(e){if(token===directorToken)console.warn(e.message)}finally{if(token===directorToken){state.director=false;stopSpeech();document.querySelector('#present').textContent='▶ Present demo';phone.querySelector('.tap-pointer').style.opacity=0}}}
// FIT_RUNTIME_START
Object.assign(state,{practicePage:0,form:3,readProgress:0,readFinished:false,readLoading:false});
const readingMarkup=()=>`${state.reading?'<span class="wave" aria-hidden="true"><i></i><i></i><i></i><i></i></span>':icon(state.readFinished?'check':'volume-2')}<span>${state.reading?'Stop':state.readFinished?'Replay':'Listen'}</span><span class="listen-track" role="progressbar" aria-label="Reading progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(state.readProgress*100)}"><span style="transform:scaleX(${state.readProgress})"></span></span>`;
const fitListen=()=>`<button class="listen ${state.reading?'speaking':''} ${state.readLoading?'loading':''} ${state.readFinished?'finished':''}" data-action="listen" aria-label="${state.reading?'Stop reading':'Read this screen aloud'}">${readingMarkup()}</button>`;
listen=fitListen;
const say=(s,tag='p',cls='')=>`<${tag} data-narrate class="${cls}">${s}</${tag}>`;
const shortIntro=(title,copy='')=>`<div class="intro">${say(title,'h1')}${copy?say(copy,'p','muted'):''}</div>`;
function lessonPage(){return Object.entries(lessons).slice(state.practicePage*3,state.practicePage*3+3)}
function spokenVisible(){return [...phone.querySelectorAll('[data-narrate]')].filter(el=>el.getBoundingClientRect().height>0).map(el=>el.dataset.say||el.textContent.trim()).filter(Boolean).join('. ').replace(/\.\./g,'.').replace(/\s+/g,' ').trim()}
function prompt(){return spokenVisible()}
let readFrame=0,settleSpeech=null;
function updateReading(){phone.querySelectorAll('.listen').forEach(el=>{el.classList.toggle('speaking',state.reading);el.classList.toggle('loading',state.readLoading);el.classList.toggle('finished',state.readFinished);el.innerHTML=readingMarkup();el.setAttribute('aria-label',state.reading?'Stop reading':'Read this screen aloud')})}
function progressReading(){cancelAnimationFrame(readFrame);const tick=()=>{if(!state.reading)return;if(Number.isFinite(narration.duration)&&narration.duration>0){state.readProgress=Math.min(.999,narration.currentTime/narration.duration);phone.querySelectorAll('.listen-track').forEach(el=>{el.setAttribute('aria-valuenow',Math.round(state.readProgress*100));el.firstElementChild.style.transform=`scaleX(${state.readProgress})`})}readFrame=requestAnimationFrame(tick)};readFrame=requestAnimationFrame(tick)}
function stopSpeech(){speechToken++;cancelAnimationFrame(readFrame);if('speechSynthesis'in window)speechSynthesis.cancel();narration.pause();narration.onended=null;narration.onerror=null;narration.onplaying=null;state.reading=false;state.readLoading=false;state.readProgress=0;state.readFinished=false;if(settleSpeech){settleSpeech();settleSpeech=null}updateReading()}
function speak(words){if(state.muted||!words)return Promise.resolve();stopSpeech();const token=speechToken;state.reading=true;state.readLoading=true;updateReading();return new Promise(resolve=>{settleSpeech=resolve;const end=(ok=true)=>{if(token!==speechToken){resolve();return}cancelAnimationFrame(readFrame);state.readProgress=ok?1:0;state.readFinished=ok;state.readLoading=false;state.reading=false;settleSpeech=null;updateReading();resolve()};if(AUDIO[words]){narration.src=AUDIO[words];narration.currentTime=0;narration.playbackRate=state.rate/.93;narration.onplaying=()=>{state.readLoading=false;updateReading();progressReading()};narration.onended=()=>end(true);narration.onerror=()=>end(false);narration.play().catch(()=>end(false));return}if(!('speechSynthesis'in window)){end(false);return}const u=new SpeechSynthesisUtterance(words);u.lang='en-US';u.rate=state.rate;u.pitch=1.05;u.onstart=()=>{state.readLoading=false;updateReading()};u.onboundary=e=>{state.readProgress=Math.min(.99,e.charIndex/words.length);updateReading()};u.onend=()=>end(true);u.onerror=()=>end(false);speechSynthesis.speak(u)})}
function pager(page,total,key='practice'){return `<div class="pager"><button data-page="${key}:${page-1}" ${page===0?'disabled':''} aria-label="Previous page">${icon('arrow-left')} Previous</button><span data-narrate>Page ${page+1} of ${total}</span><button data-page="${key}:${page+1}" ${page===total-1?'disabled':''} aria-label="Next page">Next ${icon('arrow-right')}</button></div>`}
function renderGame(options={}){renderToken++;state.readProgress=0;state.readFinished=false;const f=family();let head='',content='',foot='';const H=(title,opts={})=>header(title,{audio:true,...opts});
if(state.screen==='welcome'){head=H('',{logo:true});content=`<div class="pad welcome-fit">${shortIntro('Your beast.<br>Your adventure!')}<div class="hero four elastic-art">${families.map(x=>sprite(x,1)).join('')}</div><div class="trio">${[['compass','Explore'],['gem','Solve'],['paw-print','Grow']].map(([i,t])=>`<div>${icon(i)}${say(t,'span')}</div>`).join('')}</div><button class="link parent-link" data-action="settings">For parents ${icon('chevron-right')}</button></div>`;foot=action('Play','start')}
else if(state.screen==='nickname'){head=H('Your explorer',{back:true});content=`<div class="pad">${shortIntro('Pick a nickname.')}<div class="hero elastic-art">${sprite(f,1)}</div><label class="field"><span data-narrate>Nickname</span><input id="nickname" maxlength="16" autocomplete="off" value="${escape(state.nickname)}"></label></div>`;foot=action('Next','save-name')}
else if(state.screen==='eggs'){head=H('Your beast',{back:true});content=`<div class="pad">${shortIntro('Pick your beast.')}<div class="egg-grid fit-grid">${families.map((x,i)=>`<button class="egg ${i===state.family?'active':''}" data-family="${i}" aria-pressed="${i===state.family}" style="--element:${x.color};--soft:${x.soft}"><span class="egg-art"><img src="assets/${x.key}-egg.webp" alt="${x.element} egg"></span>${say(x.name,'strong')}${say(x.element,'small')}</button>`).join('')}</div></div>`;foot=action('Choose '+f.name,'hatch')}
else if(state.screen==='hatch'){head=H('A new friend',{back:true});content=`<div class="pad result">${shortIntro('Hello, '+f.name+'!')}<div class="hero evolve elastic-art">${sprite(f,1)}</div>${say('Play quests. Help your beast grow.','p','muted')}</div>`;foot=action('Let’s go','camp')}
else if(state.screen==='camp'){head=H('Camp',{brand:true,gear:true});content=`<div class="pad camp-fit"><div class="hero elastic-art">${sprite()}</div><div class="camp-summary"><div>${say(f.name,'h2')}${say(['','Hatchling','Scout','Guardian','Champion','Titan'][state.stage],'span','muted')}</div><span class="pill" data-narrate>${icon('apple')} ${state.food} ${state.food===1?'apple':'apples'}</span></div><div class="progress-track"><span style="width:${state.xp%30/30*100}%"></span></div>${say(`${state.xp%30} of 30 XP · ${state.progress} of 5 quests done`,'small')}<div class="two"><button data-go="food" data-narrate>${icon('apple')} Feed</button><button data-go="beasts" data-narrate>${icon('book-open')} My beasts</button></div><button class="primary" data-go="map" data-narrate>Explore</button></div>`;foot=nav('camp')}
else if(state.screen==='map'){head=H('Adventure');content=`<div class="map-fit"><div class="map-art"><div class="world"><div class="map-progress" data-narrate>${state.progress} of 5 done</div>${[[128,428],[281,322],[104,252],[274,133],[176,68]].map(([x,y],i)=>`<button class="quest-node ${i<state.progress?'done':i===state.progress?'current':'locked'}" style="left:${x/393*100}%;top:${y/490*100}%" data-quest="${i}" aria-label="${quests[i][0]}, ${i<state.progress?'complete':i===state.progress?'play next':'locked'}">${icon(i<state.progress?'check':i===state.progress?'flag':'lock-keyhole')}${i===state.progress?'<span class="tag">Next</span>':''}</button>`).join('')}</div></div><div class="map-actions">${say(state.progress===5?'You lit the lighthouse!':quests[state.progress][0],'h2')}<button class="primary" data-action="play-next" data-narrate>${state.progress===5?'My camp':'Play quest'}</button><button class="link" data-go="practice" data-narrate>Practice any skill ${icon('chevron-right')}</button></div></div>`;foot=nav('map')}
else if(state.screen==='practice'){head=H('Practice',{back:true});content=`<div class="pad practice-fit">${shortIntro('Pick a quest.')}<div class="quest-batch">${lessonPage().map(([k,l])=>`<button class="trail" data-practice="${k}"><span class="tile">${icon(k==='count'||k==='subtract'?'apple':k==='fraction'?'shield-check':'gem')}</span><span class="words">${say(l.title,'strong')}</span>${icon('chevron-right')}</button>`).join('')}</div>${pager(state.practicePage,3)}</div>`;foot=nav('map')}
else if(state.screen==='lesson'||state.screen==='hint'){const l=lessons[state.lesson],hint=state.screen==='hint';head=H(hint?'A little help':'Quest '+(state.worldGoal||'practice'),{back:true});content=`<div class="pad lesson-fit">${shortIntro(hint?'Let’s work it out.':l.title,hint?l.hint:l.copy)}<div class="visual elastic-art">${visual(state.lesson,hint)}</div>${hint?`${say(l.equation,'h2','equation-hint')}`:`${say(l.question,'h3')}<div class="answers">${l.values.map(v=>`<button class="answer" data-answer="${escape(v)}" data-narrate>${escape(v)}</button>`).join('')}</div>`}</div>`;foot=action(hint?'Try again':'Help me',hint?'try-again':'help',!hint)}
else if(state.screen==='reward'){head=H('Quest complete');content=`<div class="pad result">${shortIntro('You did it!')}<div class="celebrate elastic-art">${icon('flag')}${Array.from({length:12},(_,i)=>`<span class="star" style="left:${10+i*7}%;top:65%;--x:${(i-6)*15}px;animation-delay:${i*.04}s">✦</span>`).join('')}</div><div class="reward-grid"><div class="card">${icon('zap')}${say('+10 XP','strong')}</div><div class="card">${icon('apple')}${say('+1 Apple','strong')}</div></div><div class="progress-track"><span style="width:${state.xp%30/30*100}%"></span></div>${say(`${state.xp%30} of 30 XP to the next form`,'small')}</div>`;foot=action(state.pendingEvolution?'See my beast grow':'Keep exploring','claim')}
else if(state.screen==='evolve'){head=H('A bigger beast');content=`<div class="pad result">${shortIntro(f.name+' grew!')}<div class="hero evolve elastic-art">${sprite()}</div>${say(['','Hatchling','Scout','Guardian','Champion','Titan'][state.stage],'h2')}</div>`;foot=action('Keep exploring','finish-evolve')}
else if(state.screen==='food'){head=H('Snack time',{back:true});content=`<div class="pad result">${shortIntro(state.food?'Time for a snack?':'Let’s find more food.')}<div class="hero elastic-art">${sprite()}</div><div class="snack-count">${icon('apple')}${say(state.food+' '+(state.food===1?'apple':'apples')+' in your bag','h2')}</div></div>`;foot=action(state.food?'Feed my beast':'Find a quest',state.food?'feed':'map')}
else if(state.screen==='beasts'){head=H('My beasts',{back:true});content=`<div class="pad">${shortIntro('Meet the beasts.')}<div class="family-grid fit-grid">${families.map((x,i)=>`<button class="family" data-detail="${i}"><span class="egg-art">${sprite(x,2)}</span>${say(x.name,'strong')}${say(x.element,'small')}</button>`).join('')}</div></div>`;foot=nav('beasts')}
else if(state.screen==='family'){const x=families[state.detail||0];head=H(x.name,{back:true});content=`<div class="pad result family-fit">${shortIntro('Watch them grow.')}<div class="hero elastic-art">${sprite(x,state.form)}</div>${say(['','Hatchling','Scout','Guardian','Champion','Titan'][state.form],'h2')}<div class="form-progress">${[1,2,3,4,5].map(n=>`<span class="${state.form===n?'active':''}">${n}</span>`).join('')}</div>${pager(state.form-1,5,'form')}</div>`;foot=action('My camp','camp')}
const narratedFooter=foot.replace(/(<button[^>]*data-action="[^"]+")/g,'$1 data-narrate');phone.dataset.screen=state.screen;phone.innerHTML=head+`<div class="game-view screen-enter">${content}</div>`+narratedFooter+'<div class="tap-pointer" aria-hidden="true"></div><span class="sr-only" id="announcer" aria-live="polite"></span>';bind();phone.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{stopSpeech();const [key,p]=b.dataset.page.split(':');if(key==='form')state.form=+p+1;else state.practicePage=+p;render();if(state.autoRead&&!state.director)setTimeout(()=>speak(prompt()),240)});fitScene()}
function fitScene(){const area=phone.querySelector('.game-view');if(!area)return;const foot=phone.querySelector('.bottom');area.style.bottom=(foot?.offsetHeight||0)+'px';const hero=area.querySelector('.hero');if(hero){const space=hero.clientHeight;const scale=Math.min(.9,Math.max(.4,(space-20)/416));hero.style.setProperty('--sprite-height',(512*scale)+'px');hero.style.setProperty('--sprite-bottom',(-32*scale+8)+'px')}const art=area.querySelector('.map-art');if(art){const w=Math.min(art.clientWidth,art.clientHeight*1122/1402);const world=art.querySelector('.world');world.style.width=w+'px';world.style.height=w*1402/1122+'px'}}
window.addEventListener('resize',fitScene);

