// Friendly explanations with speech-aligned attention, never automatic answers.
Object.assign(state,{guideStep:-1,guideTarget:'',guideKey:'',guideItem:-1});
let guideRaf=0,guideResolve=null,activeGuide=null,activeGuideStep=-1,activeGuideItem=-1;
function guideKey(){if(state.screen==='lesson'||state.screen==='hint')return state.screen+'-'+state.lesson;if(state.screen==='practice')return 'practice-'+state.practicePage;if(state.screen==='map')return state.progress===5?'map-done':state.progress===0?'map-start':'map-progress';if(state.screen==='food'&&!state.food)return 'food-empty';return state.screen}
function prompt(){return GUIDES[guideKey()]?.text||''}
function guideWord(text){const word=text.toLowerCase().replace(/[^a-z0-9]/g,'');return ['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve'][Number(word)]||word}
function clearGuideHighlights(){phone.querySelectorAll('.guide-focus,.guide-pulse,.guide-breathe').forEach(el=>el.classList.remove('guide-focus','guide-pulse','guide-breathe'));state.guideTarget='';state.guideStep=-1;state.guideItem=-1;activeGuideStep=-1;activeGuideItem=-1}
function setGuideAttention(g,time){let index=g.steps.findIndex((s,i)=>time>=s.start&&(i===g.steps.length-1||time<g.steps[i+1].start));if(index<0)index=0;const s=g.steps[index];if(!s.target)return;const items=[...phone.querySelectorAll(s.target)];if(!items.length)return;let item=-1;if(s.motion==='sequence'){item=Math.min(items.length-1,Math.max(0,Math.floor((time-s.start)/Math.max(.1,s.end-s.start)*items.length)));if(s.cues){const cueTimes=s.cues.map(c=>g.words.find(w=>w.time>=s.start&&w.time<s.end&&guideWord(w.text)===c)?.time??s.start);item=Math.max(0,cueTimes.findLastIndex(t=>time>=t))}}if(index===activeGuideStep&&item===activeGuideItem)return;clearGuideHighlights();activeGuideStep=index;activeGuideItem=item;state.guideStep=index;state.guideItem=item;state.guideTarget=s.target;const targets=item<0?items:[items[item]];targets.forEach(el=>{el.classList.add('guide-focus');if(s.motion==='pulse'||s.motion==='breathe'||s.motion==='sequence')el.classList.add(s.motion==='breathe'?'guide-breathe':'guide-pulse')});phone.dataset.guideStep=String(index);phone.dataset.guideTarget=s.target}
function updateReading(){phone.querySelectorAll('.listen').forEach(el=>{el.classList.toggle('speaking',state.reading);el.classList.toggle('loading',state.readLoading);el.classList.toggle('finished',state.readFinished);el.innerHTML=readingMarkup();el.setAttribute('aria-label',state.reading?'Stop the voice guide':state.readFinished?'Replay the voice guide':'Hear a helpful guide')})}
function stopSpeech(){speechToken++;cancelAnimationFrame(guideRaf);cancelAnimationFrame(readFrame);narration.pause();narration.onended=null;narration.onerror=null;narration.onplaying=null;state.reading=false;state.readLoading=false;state.readProgress=0;state.readFinished=false;activeGuide=null;clearGuideHighlights();if(guideResolve){guideResolve();guideResolve=null}updateReading()}
function speak(words){if(state.muted||!words)return Promise.resolve();stopSpeech();const key=Object.hasOwn(GUIDES,guideKey())&&GUIDES[guideKey()].text===words?guideKey():Object.keys(GUIDES).find(k=>GUIDES[k].text===words);const g=GUIDES[key];if(!g)return Promise.resolve();activeGuide=g;state.guideKey=key;state.reading=true;state.readLoading=true;const token=speechToken;updateReading();return new Promise(resolve=>{guideResolve=resolve;const end=ok=>{if(token!==speechToken){resolve();return}cancelAnimationFrame(guideRaf);clearGuideHighlights();state.reading=false;state.readLoading=false;state.readProgress=ok?1:0;state.readFinished=ok;guideResolve=null;activeGuide=null;updateReading();resolve()};const tick=()=>{if(token!==speechToken||!state.reading)return;const duration=narration.duration;if(Number.isFinite(duration)&&duration>0){state.readProgress=Math.min(.999,narration.currentTime/duration);phone.querySelectorAll('.listen-track').forEach(el=>{el.setAttribute('aria-valuenow',Math.round(state.readProgress*100));el.firstElementChild.style.transform=`scaleX(${state.readProgress})`});setGuideAttention(g,narration.currentTime)}guideRaf=requestAnimationFrame(tick)};narration.src=g.audio;narration.currentTime=0;narration.playbackRate=state.rate/.93;narration.preservesPitch=true;narration.onplaying=()=>{state.readLoading=false;updateReading();guideRaf=requestAnimationFrame(tick)};narration.onended=()=>end(true);narration.onerror=()=>end(false);narration.play().catch(()=>end(false))})}
function render(options={}){clearGuideHighlights();renderGame(options);phone.querySelectorAll('.listen').forEach(el=>el.setAttribute('aria-label','Hear a helpful guide'));phone.dataset.guideKey=guideKey();phone.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{stopSpeech();state.family=+b.dataset.family;render();if(!state.director)speak(GUIDES['egg-'+family().key].text)})}

// GUIDE_RUNTIME_END
document.querySelector('#present').onclick=present;document.querySelector('#fullscreen').onclick=()=>phone.requestFullscreen?.();document.querySelector('#reset').onclick=()=>{directorToken++;state.director=false;stopSpeech();Object.assign(state,{progress:0,xp:0,food:1,stage:1,worldGoal:0,pendingEvolution:false});document.querySelector('#present').textContent='▶ Present demo';go('welcome',{read:false})};document.addEventListener('keydown',e=>{if(e.key==='Escape'){phone.querySelector('.modal-backdrop')?.remove();if(state.reading)stopSpeech()}});window.addEventListener('pagehide',stopSpeech);render();window.numbeast={state,go,speak,prompt,stopSpeech,present};
